/** Whether a building (by internal game name) can be buffed with a regular building buff. */
export function isBuffableBuildingName(buildingName) {
    return BUFFABLE_WORKYARDS.has(buildingName);
}

/** Whether the buff exists in the XML catalog. */
export function isKnownBuff(buffName) {
    return !!BUFF_TARGETS[buffName];
}

/** Whether the item is a building-targeted buff (excludes AddResource / FillDeposit / Adventure / etc). */
export function isBuildingBuff(buffName) {
    const spec = BUFF_TARGETS[buffName];
    // Unknown names are kept (fail-open) so freshly added game content still shows up.
    if (!spec) return true;
    return spec.tt === 'Building';
}

/** Whether a specific buff (by buffName_string) can be applied to a specific building. */
export function canBuffTarget(buffName, buildingName) {
    const spec = BUFF_TARGETS[buffName];
    // Unknown buff -> fall back to the generic workyard whitelist.
    if (!spec || !spec.t) return BUFFABLE_WORKYARDS.has(buildingName);
    if (spec.tt && spec.tt !== 'Building') return false;
    for (const t of spec.t) {
        if (t === 'Workyard') {
            if (BUFFABLE_WORKYARDS.has(buildingName)) return true;
        } else if (t === buildingName) {
            return true;
        }
    }
    return false;
}

/** Whether a buff can be applied on a friend's zone. */
export function isFriendZoneBuff(buffName) {
    const spec = BUFF_TARGETS[buffName];
    return !spec || spec.z.includes('Friend');
}

/** Buff durations in seconds: { Player, Friend } or null for instant/unknown buffs. */
export function getBuffDurations(buffName) {
    const spec = BUFF_TARGETS[buffName];
    return spec && spec.d ? spec.d : null;
}

/** Format seconds as "2h 30m" / "45m" / "30s". */
export function formatBuffDuration(seconds) {
    if (!seconds || seconds <= 0) return '';
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    const parts = [];
    if (h) parts.push(h + 'h');
    if (m) parts.push(m + 'm');
    if (!h && !m) parts.push(s + 's');
    return parts.join(' ');
}
